CREATE TABLE "balance_snapshot" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "balance_snapshot_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"amount" double precision NOT NULL,
	"asOf" timestamp with time zone NOT NULL,
	"createdAt" timestamp with time zone NOT NULL
);
